settings.custom_liquid:
{% if cart.item_count > 0 %}
  <div class="boschino-cart-note-wrap" id="BoschinoCartNote">
    <div class="boschino-cart-note-title">Přidat poznámku k objednávce</div>

    <textarea
      class="boschino-cart-note-textarea"
      name="note"
      id="CartNote"
      placeholder="Napište upřesnění k objednávce..."
    >{{ cart.note }}</textarea>
  </div>

  <style>
    .boschino-cart-note-wrap{
      background:#fff;
      padding:14px 16px 16px;
      box-shadow:0 12px 24px rgba(0,0,0,.08);
      position:relative;
      width:100%;
      max-width: 760px;
    }

    .boschino-cart-note-wrap::before{
      content:"";
      position:absolute;
      left:0; right:0; top:0;
      height:6px;
      background:linear-gradient(to bottom,#1f2a7a 0 4px,#e2001a 4px 6px);
    }

    .boschino-cart-note-title{
      margin:6px 0 10px;
      font-size:13px;
      font-weight:400;
      color:#101820;
    }

    .boschino-cart-note-textarea{
      width:100%;
      min-height:110px;
      padding:10px 12px;
      border:1px solid rgba(16,24,32,.25);
      border-radius:0;
      background:#fff;
      box-shadow:none;
      outline:none;
      resize:vertical;
    }

    .boschino-cart-note-textarea:focus{
      border-color:rgba(226,0,26,.55);
      box-shadow:none;
    }
  </style>

  <script>
    document.addEventListener('DOMContentLoaded', function () {
      var noteWrap = document.getElementById('BoschinoCartNote');
      var noteEl = document.getElementById('CartNote');
      if (!noteWrap || !noteEl) return;

      // Varianta A: zakázat Enter (žádné odřádkování)
      noteEl.addEventListener('keydown', function (e) {
        if (e.key === 'Enter') {
          e.preventDefault();
        }
      });

      // Ukládání poznámky do košíku (aby se propsala i do objednávky)
      var t;
      function saveNote() {
        try {
          return fetch('/cart/update.js', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
            body: JSON.stringify({ note: noteEl.value })
          });
        } catch (e) {
          return Promise.resolve();
        }
      }

      // Debounce při psaní
      noteEl.addEventListener('input', function () {
        clearTimeout(t);
        t = setTimeout(saveNote, 400);
      });

      // Pojistka před odchodem na checkout
      function bindCheckoutGuards() {
        var els = [];
        els = els.concat([].slice.call(document.querySelectorAll('a[href*="/checkout"]')));
        els = els.concat([].slice.call(document.querySelectorAll('button[name="checkout"], input[name="checkout"]')));
        els.forEach(function (el) {
          el.addEventListener('click', function () { saveNote(); }, { capture: true });
        });
      }
      bindCheckoutGuards();

      // přesun vedle pokladny (do levého sloupce), pokud existuje footer
      var footer = document.querySelector('.cart__footer');
      if (footer) {
        footer.insertBefore(noteWrap, footer.firstChild);
      }

      // pojistka: držet uvnitř cart formu, pokud existuje
      var cartForm = document.querySelector('form#cart') || document.querySelector('form[action*="/cart"]');
      if (cartForm && !cartForm.contains(noteWrap)) {
        cartForm.appendChild(noteWrap);
        if (footer) footer.insertBefore(noteWrap, footer.firstChild);
      }
    });
  </script>
{% endif %}
